// SOURCE database = the authoritative / desired state.
// In a real sync this node would be an HTTP / Postgres / Supabase / Data Table
// read of the system of record. Keyed on `sku`.
return [
  { json: { sku: 'SKU-1', name: 'Widget',  price: 10, stock: 100 } },
  { json: { sku: 'SKU-2', name: 'Gadget',  price: 25, stock: 40  } },
  { json: { sku: 'SKU-3', name: 'Gizmo',   price: 15, stock: 7   } }
];

// TARGET database = the copy being kept in sync (current state).
// SKU-1 is identical, SKU-2 has a stale price (20 vs 25), SKU-4 no longer
// exists in source, SKU-3 does not exist here yet. Keyed on `sku`.
return [
  { json: { sku: 'SKU-1', name: 'Widget',    price: 10, stock: 100 } },
  { json: { sku: 'SKU-2', name: 'Gadget',    price: 20, stock: 40  } },
  { json: { sku: 'SKU-4', name: 'Doohickey', price: 30, stock: 5   } }
];

// 'Different' = key matches but fields differ -> rows to UPDATE in target.
// resolve=preferInput1 means these carry the SOURCE (desired) values.
return items.map(i => ({ json: { action: 'UPDATE', table: 'target', ...i.json } }));
